export default function next({ rows, configRows, previous }) {
  if (!Array.isArray(rows) || !Array.isArray(configRows) || rows.length < 1)
    throw Error("Missing sheets");
  const headers = rows[0].map(String),
    needed = ["ID", "Action", "Status", "Scheduled", "Title", "final"];
  if (needed.some((k) => !headers.includes(k)) || new Set(headers).size !== headers.length)
    throw Error("Expected unique Schedule headers");
  const config = Object.fromEntries(
    configRows
      .slice(1)
      .filter((r) => r[0])
      .map((r) => [String(r[0]), String(r[1] ?? "")]),
  );
  let index = previous?.index ?? 1;
  while (index < rows.length) {
    const raw = rows[index],
      row = Object.fromEntries(headers.map((h, i) => [h, raw[i] ?? ""]));
    index++;
    if (!row.ID || !row.Action || row.Action === row.Status) continue;
    if (
      rows.slice(1).filter((r) => String(r[headers.indexOf("ID")]) === String(row.ID)).length !== 1
    )
      throw Error("Schedule IDs must be unique");
    if (row.Action === "publish") {
      const date = String(row.Scheduled).replace(" ", "T") + "Z";
      if (!/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ$/.test(date) || !Number.isFinite(Date.parse(date)))
        throw Error("Expected UTC Scheduled timestamp");
      if (Date.parse(date) > Date.now()) continue;
      if (!row.Title || !row.final) throw Error("Publication requires Title and final");
      return {
        state: { index },
        more: true,
        row,
        kind: "publish",
        prompt: "",
        model: "",
        rowNumber: index,
      };
    }
    const lookup = (k) => row[k] || config[k] || config[k + String(row.Context ?? "")] || "";
    const expand = (s) =>
      String(s ?? "")
        .replace(/\{\{\s*([^}]+)\s*\}\}/g, (_, k) => String(lookup(k.trim())))
        .trim();
    const prompt = expand(config["prompt_" + row.Action]),
      model = expand(config["prompt_" + row.Action + "_model"]);
    if (!prompt || !model) throw Error("Missing action prompt or model");
    return { state: { index }, more: true, row, kind: "generate", prompt, model, rowNumber: index };
  }
  return {
    state: { index },
    more: false,
    row: {},
    kind: "done",
    prompt: "",
    model: "",
    rowNumber: 0,
  };
}

