export default async function plan(
  { row, rowNumber, headers, kind, model, prompt, result, acknowledge, resolution },
  ctx,
) {
  const key = "blog-schedule:" + String(row.ID) + ":" + String(row.Action),
    orig = JSON.stringify(row);
  let s = await ctx.state.get(key);
  if (s && s.orig !== orig) throw Error("Restore original row while checkpoint exists: " + key);
  if (!s) s = { orig, phase: kind === "publish" ? "publish-ready" : "model-ready" };
  if (s.phase.endsWith("-pending")) {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending write " + key + " " + s.phase);
    const phase = s.phase.slice(0, -8);
    if (resolution === "absent") s.phase = phase + "-ready";
    else s.phase = phase === "publish" ? "log-ready" : phase === "log" ? "sheet-ready" : "done";
  }
  if (s.phase === "model-ready" && result) {
    const choice = result.choices?.[0];
    if (choice?.finish_reason !== "stop" || typeof choice.message?.content !== "string")
      throw Error("Incomplete model response");
    let data;
    try {
      data = JSON.parse(choice.message.content);
    } catch {
      throw Error("Expected model JSON object");
    }
    if (!data || Array.isArray(data) || typeof data !== "object") throw Error("Expected object");
    const full = data.Fulltext ?? data;
    data[row.Action] = typeof full === "string" ? full : JSON.stringify(full);
    const merged = { ...row };
    for (const [k, v] of Object.entries(data))
      if (headers.includes(k)) {
        let a = String(row[k] ?? ""),
          b = typeof v === "string" ? v : JSON.stringify(v);
        merged[k] = a && b ? a + "\n---\n" + b : a || b;
      }
    merged.Status = row.Action;
    s.values = [headers.map((h) => merged[h] ?? "")];
    s.phase = "log-ready";
  }
  if (kind === "publish" && !s.values) {
    const next = { ...row, Status: "publish" };
    s.values = [headers.map((h) => next[h] ?? "")];
  }
  let action =
    s.phase === "model-ready"
      ? "model"
      : s.phase.endsWith("-ready")
        ? s.phase.slice(0, -6)
        : "done";
  if (["publish", "log", "sheet"].includes(action)) {
    s.phase = action + "-pending";
    await ctx.state.set(key, s);
  } else if (action === "done") await ctx.state.set(key, s);
  const column = (n) => {
    let out = "";
    while (n) {
      n--;
      out = String.fromCharCode(65 + (n % 26)) + out;
      n = Math.floor(n / 26);
    }
    return out;
  };
  return {
    key,
    action,
    model,
    messages: [{ role: "user", content: prompt }],
    title: String(row.Title ?? ""),
    content: String(row.final ?? ""),
    values: s.values ?? [[]],
    range: `Schedule!A${rowNumber}:${column(headers.length)}${rowNumber}`,
    log: [
      [
        new Date().toISOString(),
        "info",
        `${kind === "publish" ? "Published post " + (s.postId ?? "confirmed") : "Status " + row.Action} for row ${rowNumber}`,
      ],
    ],
  };
}

