export default async function confirm({ key, phase, result }, ctx) {
  const s = await ctx.state.get(key);
  if (s?.phase !== phase + "-pending") throw Error("Unexpected checkpoint");
  if (phase === "publish" && (!result?.id || result.status !== "publish"))
    throw Error("Inspect WordPress post");
  if ((phase === "log" || phase === "sheet") && !(result?.updatedRows > 0))
    throw Error("Inspect Sheets write");
  if (phase === "publish") s.postId = result.id;
  s.phase = phase === "publish" ? "log-ready" : phase === "log" ? "sheet-ready" : "done";
  await ctx.state.set(key, s);
  return { ok: true };
}

